import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as n}from"./chunks/Tags.BJ536pW3.js";import{c as s,o as r,j as i,G as t,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Full-Year Continuing Appropriations and Extensions Act, 2025","description":"","frontmatter":{"legisId":"2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025","title":"Full-Year Continuing Appropriations and Extensions Act, 2025","displayTitle":"Full-Year Continuing Appropriations and Extensions Act, 2025","lawNumber":"119-4","billNumber":"H.R. 1968","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ4.xml","publishDate":"2025-03-15T00:00:00-05:00","industries":["government-operations","healthcare","defense"],"agencies":["Department of Defense","Department of Veterans Affairs","Federal Emergency Management Agency","Office of Management and Budget","Commodity Futures Trading Commission"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Full-Year Continuing Appropriations and Extensions Act, 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Full-Year Continuing Appropriations and Extensions Act, 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025\\",\\"datePublished\\":\\"2025-03-15T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025.md","filePath":"congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-03-15-full-year-continuing-appropriations-and-extensions-act-2025.md"},f=Object.assign(d,{setup(c){return(p,e)=>(r(),s("div",null,[e[0]||(e[0]=i("h1",{id:"full-year-continuing-appropriations-and-extensions-act-2025",tabindex:"-1"},[l("Full-Year Continuing Appropriations and Extensions Act, 2025 "),i("a",{class:"header-anchor",href:"#full-year-continuing-appropriations-and-extensions-act-2025","aria-label":'Permalink to "Full-Year Continuing Appropriations and Extensions Act, 2025"'},"​")],-1)),t(a),t(n,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Saturday, March 15, 2025. Public Law 119-4, H.R. 1968.</p><p><strong>Headline:</strong> The law funds most federal operations through September 30, 2025, and extends key health, cybersecurity, drug-control, and enforcement authorities.</p><p><strong>Why it matters:</strong> It avoids a government shutdown, maintains major public services and benefits, and gives agencies full-year funding generally based on fiscal year 2024 levels.</p><p><strong>What the law does:</strong></p><ul><li>Funds most federal departments and programs through fiscal year 2025, with targeted increases, reductions, transfers, rescissions, and advance funding.</li><li>Sets specific funding for defense, veterans, disaster relief, nutrition, rental assistance, aviation, wildfire response, and other priorities.</li><li>Extends community health center, health workforce, diabetes, Medicare, Medicaid, telehealth, hospital-at-home, and health security policies through September 2025.</li><li>Delays scheduled Medicaid hospital payment cuts and revises their schedule through fiscal year 2028.</li><li>Extends whistleblower, counter-drone, cybersecurity, fentanyl scheduling, and criminal assessment authorities through September 2025.</li><li>Requires agency spending plans and monthly Office of Management and Budget reports to Congress while excluding prior-year earmarks.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Federal agencies, employees, contractors, veterans, service members, and communities relying on disaster and wildfire response.</li><li>Medicare and Medicaid beneficiaries, hospitals, community health centers, healthcare workers, and patients using telehealth or hospital-at-home services.</li><li>Families receiving nutrition, housing, disability, child support, foster care, and other federal assistance.</li><li>Financial-market whistleblowers, protected federal facilities, cybersecurity operators, and people subject to fentanyl-related or criminal enforcement rules.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Federal services and benefit programs generally continue without a funding lapse through September 30, 2025.</li><li>Eligible patients retain specified telehealth, hospital-at-home, ambulance, prescription drug, and community health services for the extension period.</li></ul><p><strong>Context:</strong> Most programs continue under fiscal year 2024 funding terms unless the law specifies a different amount or rule.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="division-a-full-year-continuing-appropriations-act-2025" tabindex="-1">DIVISION A, FULL-YEAR CONTINUING APPROPRIATIONS ACT, 2025 <a class="header-anchor" href="#division-a-full-year-continuing-appropriations-act-2025" aria-label="Permalink to &quot;DIVISION A, FULL-YEAR CONTINUING APPROPRIATIONS ACT, 2025&quot;">​</a></h3><p>This division funds most federal departments and programs through September 30, 2025, generally using fiscal year 2024 funding levels and rules while setting different amounts for many specific accounts. It also provides targeted increases, reductions, advance funding, transfers, and rescissions across defense, veterans, disaster relief, agriculture, health, transportation, housing, energy, and other federal activities.</p><p><strong>Key takeaways:</strong></p><ul><li>Most federal programs continue through fiscal year 2025 under their fiscal year 2024 funding terms unless this division provides a specific exception.</li><li>The division sets detailed funding levels for major agencies and programs, including the Department of Defense, the Department of Veterans Affairs, FEMA disaster relief, WIC, rental assistance, aviation operations, and wildfire response.</li><li>It provides advance funding for fiscal year 2026 benefits and services, including Medicaid, Supplemental Security Income, foster care, child support programs, disabled coal miner benefits, and veterans programs.</li><li>Fiscal year 2024 earmarks do not apply to the funds provided by this division.</li><li>Federal departments and agencies must submit detailed fiscal year 2025 spending plans, and the Office of Management and Budget must report monthly to Congress on obligations and compare them with fiscal year 2024 spending.</li><li>The division rescinds selected unused funds, permits specified transfers and reprogramming, and preserves emergency or disaster designations for qualifying funds.</li></ul><h3 id="division-b-health" tabindex="-1">DIVISION B, HEALTH <a class="header-anchor" href="#division-b-health" aria-label="Permalink to &quot;DIVISION B, HEALTH&quot;">​</a></h3><p>This division extends funding and authority through September 30, 2025, for a range of public health, Medicare, Medicaid, and human services programs. It supports community health centers, health workforce and diabetes programs, preserves several Medicare payment and telehealth policies, continues health security authorities, and delays scheduled Medicaid hospital payment reductions.</p><p><strong>Key takeaways:</strong></p><ul><li>It provides approximately $2.14 billion for community health centers, $173 million for the National Health Service Corps, and $87.7 million for teaching health center graduate medical education for April through September 2025.</li><li>It provides approximately $79.8 million each for the Type 1 diabetes program and the Special Diabetes Program for Indians, with the funds available until spent.</li><li>It extends specified national health security authorities through September 30, 2025.</li><li>It continues through September 2025 several Medicare policies, including low-volume and Medicare-dependent hospital payments, ambulance add-on payments, the work geographic index floor, telehealth flexibilities, hospital-at-home waivers, and temporary Part D coverage of authorized oral antivirals.</li><li>It increases or extends funding for Medicare quality measures, assistance for low-income beneficiaries, the Medicare Improvement Fund, sexual risk avoidance education, personal responsibility education, and family-to-family health information centers.</li><li>It postpones scheduled Medicaid disproportionate share hospital payment reductions and revises their schedule through fiscal year 2028, while also changing the timing of Medicare sequestration adjustments.</li></ul><h3 id="division-c-other-matters" tabindex="-1">DIVISION C, OTHER MATTERS <a class="header-anchor" href="#division-c-other-matters" aria-label="Permalink to &quot;DIVISION C, OTHER MATTERS&quot;">​</a></h3><p>This division extends several federal programs, authorities, and requirements through September 30, 2025. It also excludes the budget effects of Divisions B and C from specified federal budget enforcement calculations and scorecards.</p><p><strong>Key takeaways:</strong></p><ul><li>The Commodity Futures Trading Commission whistleblower program is extended through September 30, 2025.</li><li>Federal authority to protect certain facilities and assets from unmanned aircraft is extended through September 30, 2025.</li><li>The additional special assessment on certain convicted individuals is extended through September 30, 2025.</li><li>Authorization for the National Cybersecurity Protection System is extended through September 30, 2025.</li><li>The temporary scheduling order for fentanyl-related substances is extended through September 30, 2025.</li><li>The budget effects of Divisions B and C are excluded from specified statutory and Senate PAYGO scorecards and other budget enforcement calculations.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ4.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ4.xml</a></p>',24))]))}});export{g as __pageData,f as default};
